/// Looks a color token up by its bundle name (`ink-muted`).
pub fn color_by_name(p: &Palette, name: &str) -> Option<Rgba> {
    Some(match name {
        "surface-000" => p.surface_000,
        "surface-050" => p.surface_050,
        "surface-100" => p.surface_100,
        "surface-200" => p.surface_200,
        "code-bg" => p.code_bg,
        "border-subtle" => p.border_subtle,
        "border-strong" => p.border_strong,
        "ink" => p.ink,
        "ink-muted" => p.ink_muted,
        "ink-subtle" => p.ink_subtle,
        "nav-rail" => p.nav_rail,
        "nav-surface" => p.nav_surface,
        "nav-hover" => p.nav_hover,
        "nav-selected" => p.nav_selected,
        "nav-border" => p.nav_border,
        "nav-ink" => p.nav_ink,
        "nav-ink-muted" => p.nav_ink_muted,
        "accent" => p.accent,
        "accent-hover" => p.accent_hover,
        "accent-text" => p.accent_text,
        "on-accent" => p.on_accent,
        "accent-subtle" => p.accent_subtle,
        "avatar-1" => p.avatar_1,
        "avatar-2" => p.avatar_2,
        "avatar-3" => p.avatar_3,
        "avatar-4" => p.avatar_4,
        "avatar-5" => p.avatar_5,
        "avatar-6" => p.avatar_6,
        "focus-ring" => p.focus_ring,
        "composer-edge" => p.composer_edge,
        "danger" => p.danger,
        "warning" => p.warning,
        "success" => p.success,
        "on-status" => p.on_status,
        "danger-text" => p.danger_text,
        "warning-text" => p.warning_text,
        "success-text" => p.success_text,
        "danger-subtle" => p.danger_subtle,
        "warning-subtle" => p.warning_subtle,
        "match" => p.r#match,
        "success-subtle" => p.success_subtle,
        "scrim" => p.scrim,
        "syntax-keyword" => p.syntax_keyword,
        "syntax-string" => p.syntax_string,
        "syntax-number" => p.syntax_number,
        "syntax-comment" => p.syntax_comment,
        "syntax-function" => p.syntax_function,
        "syntax-type" => p.syntax_type,
        "syntax-operator" => p.syntax_operator,
        "brand-google-blue" => p.brand_google_blue,
        "brand-google-green" => p.brand_google_green,
        "brand-google-yellow" => p.brand_google_yellow,
        "brand-google-red" => p.brand_google_red,
        _ => return None,
    })
}
